import csv
import io


def parse_csv(raw_csv: str):
    if raw_csv.startswith("\ufeff"):
        raw_csv = raw_csv[1:]

    reader = csv.reader(
        io.StringIO(raw_csv, newline=""),
        delimiter=",",
        quotechar='"',
        doublequote=True,
        strict=False,
    )
    columns = next(reader, None)
    if columns is None:
        return {"columns": [], "rows": []}

    rows = list(reader)
    width = max(26, len(columns))
    for row in rows:
        width = max(width, len(row))

    columns.extend([""] * (width - len(columns)))
    for row in rows:
        row.extend([""] * (width - len(row)))

    return {"columns": columns, "rows": rows}
